"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { requireRole } from "@/lib/permissions";
import { newStandardVersion } from "@/lib/standardVersion";
import {
  ENTITY_TYPES, GSTIN_PATTERN, INDIAN_STATES, TAN_PATTERN, TDS_FORMS, generateObligations,
  type FilingType, type ItrBasis, type Registration, type Rule, type Setting,
} from "@/lib/compliance";
import type { AppUser } from "@/lib/types";

// A master document is filed first; nothing is generated by the upload itself. Generation happens only when the
// external practitioner or PBA confirms the facts the document carries and presses Save (confirm-only).
const UPLOADERS = ["founder", "practitioner", "pba"] as const;
const CONFIRMERS = ["practitioner", "pba"] as const;
const KIND_TO_STANDARD = { gst: "gst", tan: "tan", coi: "coi" } as const;
type DocKind = keyof typeof KIND_TO_STANDARD;
type Client = Awaited<ReturnType<typeof createClient>>;

function inFolder(path: string, companyId: string) {
  if (!path.startsWith(`${companyId}/dataroom/`)) throw new Error("That file is not in this company's folder");
}

export async function uploadMasterDocument(kind: DocKind, storagePath: string, filename: string) {
  const user = await requireRole(...UPLOADERS);
  if (!(kind in KIND_TO_STANDARD)) throw new Error("Unknown document type");
  inFolder(storagePath, user.company_id);
  const supabase = await createClient();
  const { error } = await supabase.from("master_document").insert({
    company_id: user.company_id, kind, storage_path: storagePath, filename, uploaded_by_name: user.name,
  });
  if (error) throw new Error(error.message);
  // The same file is the current copy of that document in the data room (older versions kept).
  await newStandardVersion(supabase, user.company_id, KIND_TO_STANDARD[kind], storagePath, filename, "Master documents", null, user.name);
  revalidatePath("/master");
  revalidatePath("/dataroom");
}

async function loadEngineInputs(supabase: Client, companyId: string) {
  const [{ data: rules }, { data: regs }, { data: setting }] = await Promise.all([
    supabase.from("compliance_rule").select("*").eq("active", true).order("sort"),
    supabase.from("registration").select("id, kind, identifier, state, filing_type, forms, status").eq("company_id", companyId),
    supabase.from("compliance_setting").select("entity_type, effective_from, start_fy, itr_basis").eq("company_id", companyId).maybeSingle(),
  ]);
  const settings: Setting = {
    entity_type: setting?.entity_type ?? null,
    effective_from: setting?.effective_from ?? null,
    start_fy: setting?.start_fy ?? 2024,
    itr_basis: (setting?.itr_basis ?? "auto") as ItrBasis,
  };
  return { rules: (rules ?? []) as Rule[], regs: (regs ?? []) as Registration[], settings };
}

// Creates whatever rows are missing for the confirmed facts. Saving again adds only what is new.
async function generate(supabase: Client, user: AppUser, note: string): Promise<number> {
  const { rules, regs, settings } = await loadEngineInputs(supabase, user.company_id);
  const rows = generateObligations(rules, regs, settings).map((r) => ({ ...r, company_id: user.company_id, status: "pending" as const }));
  let created = 0;
  for (let i = 0; i < rows.length; i += 200) {
    const { data, error } = await supabase
      .from("obligation")
      .upsert(rows.slice(i, i + 200), { onConflict: "company_id,rule_code,registration_id,period", ignoreDuplicates: true })
      .select("id");
    if (error) throw new Error(`Could not generate the compliance rows: ${error.message}`);
    created += data?.length ?? 0;
  }
  await supabase.from("compliance_log").insert({
    company_id: user.company_id, who_name: user.name, note, result: `${created} new compliance ${created === 1 ? "entry" : "entries"}`,
  });
  return created;
}

export type ConfirmInput =
  | { docId: string; kind: "gst"; gstin: string; state: string; filingType: FilingType }
  | { docId: string; kind: "tan"; tan: string; forms: string[] }
  | { docId: string; kind: "coi"; entityType: string; incorporatedOn: string; cin?: string };

export async function confirmMasterDocument(input: ConfirmInput): Promise<{ created: number }> {
  const user = await requireRole(...CONFIRMERS);
  const supabase = await createClient();

  const { data: doc } = await supabase.from("master_document").select("id, company_id, kind, registration_id").eq("id", input.docId).maybeSingle();
  if (!doc || doc.company_id !== user.company_id) throw new Error("You don't have access to this document");
  if (doc.kind !== input.kind) throw new Error("That document is a different type");
  if (doc.registration_id) throw new Error("This document's details are already confirmed");

  let reg: { kind: "gst" | "tan" | "entity"; identifier: string; state?: string; filing_type?: FilingType; forms?: string[] };
  let note: string;

  if (input.kind === "gst") {
    const gstin = input.gstin.trim().toUpperCase();
    if (!GSTIN_PATTERN.test(gstin)) throw new Error("That GSTIN doesn't look right — it is 15 characters, like 29ABCDE1234F1Z5");
    if (!(INDIAN_STATES as readonly string[]).includes(input.state)) throw new Error("Choose the state");
    if (input.filingType !== "regular") {
      throw new Error("Only Regular GST filers are set up so far. The rules for QRMP and Composition are waiting for the company secretary to confirm them.");
    }
    reg = { kind: "gst", identifier: gstin, state: input.state, filing_type: input.filingType };
    note = `Confirmed GSTIN ${gstin} (${input.state}, Regular)`;
  } else if (input.kind === "tan") {
    const tan = input.tan.trim().toUpperCase();
    if (!TAN_PATTERN.test(tan)) throw new Error("That TAN doesn't look right — it is 10 characters, like BLRA12345B");
    const forms = input.forms.filter((f) => (TDS_FORMS as readonly string[]).includes(f));
    if (forms.length === 0) throw new Error("Choose at least one TDS form");
    reg = { kind: "tan", identifier: tan, forms };
    note = `Confirmed TAN ${tan} (forms ${forms.join(", ")})`;
  } else {
    if (!(ENTITY_TYPES as readonly string[]).includes(input.entityType)) throw new Error("Choose the entity type");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(input.incorporatedOn)) throw new Error("Enter the date of incorporation");
    reg = { kind: "entity", identifier: input.cin?.trim().toUpperCase() || "ENTITY" };
    note = `Confirmed entity: ${input.entityType}, incorporated ${input.incorporatedOn}`;
  }

  const { data: saved, error } = await supabase
    .from("registration")
    .upsert(
      { company_id: user.company_id, ...reg, status: "active", confirmed_by_name: user.name, confirmed_at: new Date().toISOString() },
      { onConflict: "company_id,kind,identifier" },
    )
    .select("id")
    .single();
  if (error) throw new Error(error.message);

  if (input.kind === "coi") {
    const { error: sErr } = await supabase.from("compliance_setting").upsert(
      { company_id: user.company_id, entity_type: input.entityType, effective_from: input.incorporatedOn, updated_at: new Date().toISOString() },
      { onConflict: "company_id" },
    );
    if (sErr) throw new Error(sErr.message);
  }
  await supabase.from("master_document").update({ registration_id: saved.id }).eq("id", doc.id);

  const created = await generate(supabase, user, note);
  revalidatePath("/master");
  revalidatePath("/compliance");
  revalidatePath("/filings");
  return { created };
}

export async function saveComplianceSettings(input: { startFy: number; itrBasis: ItrBasis; effectiveFrom: string | null; entityType: string | null }) {
  const user = await requireRole(...CONFIRMERS);
  const supabase = await createClient();
  if (!Number.isInteger(input.startFy) || input.startFy < 2020 || input.startFy > 2026) throw new Error("Choose a financial year from 2020-21 to 2026-27");
  if (!["auto", "non_audit", "audit", "tp"].includes(input.itrBasis)) throw new Error("Choose the ITR filing basis");
  if (input.effectiveFrom && !/^\d{4}-\d{2}-\d{2}$/.test(input.effectiveFrom)) throw new Error("Enter the effective-from date");
  const { error } = await supabase.from("compliance_setting").upsert(
    {
      company_id: user.company_id, start_fy: input.startFy, itr_basis: input.itrBasis,
      effective_from: input.effectiveFrom || null, entity_type: input.entityType || null, updated_at: new Date().toISOString(),
    },
    { onConflict: "company_id" },
  );
  if (error) throw new Error(error.message);
  const created = await generate(supabase, user, "Saved tracking settings");
  revalidatePath("/master");
  revalidatePath("/compliance");
  return { created };
}

// Stops tracking a registration: its unfiled rows are closed ("no longer applicable") and kept in history, never deleted.
export async function closeRegistration(registrationId: string, reason: string) {
  const user = await requireRole(...CONFIRMERS);
  const supabase = await createClient();
  const why = reason.trim() || "Registration closed";
  const { data: reg } = await supabase.from("registration").select("id, company_id, identifier, kind").eq("id", registrationId).maybeSingle();
  if (!reg || reg.company_id !== user.company_id) throw new Error("You don't have access to this registration");

  const { error } = await supabase.from("registration").update({ status: "closed", closed_at: new Date().toISOString() }).eq("id", registrationId);
  if (error) throw new Error(error.message);
  const { data: closed } = await supabase
    .from("obligation")
    .update({ closed_reason: why })
    .eq("registration_id", registrationId)
    .eq("status", "pending")
    .is("closed_reason", null)
    .select("id");
  await supabase.from("compliance_log").insert({
    company_id: user.company_id, who_name: user.name, note: `Stopped tracking ${reg.kind.toUpperCase()} ${reg.identifier} — ${why}`,
    result: `${closed?.length ?? 0} open ${closed?.length === 1 ? "entry" : "entries"} closed`,
  });
  revalidatePath("/master");
  revalidatePath("/compliance");
}
